.sri-pre-block, #sri-markdown-content {
  font-family: "JetBrains Mono", Menlo, monospace;
  font-size: 10.5px;
  line-height: 1.45;
  color: #e2e8f0;
  background: #05080e;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 5px;
  padding: 8px 10px;
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  flex: 1 1 auto;
  min-height: 260px;
  max-height: 465px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

